import{_ as l,a0 as a,w as c,s as n,ao as p,I as d,x as s,a1 as i,A as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"more、less 和 most 的区别 | LCTT x X-CMD","titleTemplate":false,"description":"more、less 和 most 的区别 | LCTT (201811) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"more、less 和 most 的区别 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"more、less 和 most 的区别 | LCTT (201811) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201811/20181108 The Difference Between more, less And most Commands","title":"more、less 和 most 的区别","tag":"201811","desc":""},"relativePath":"201811/20181108 The Difference Between more, less And most Commands.md","filePath":"[post].md"}'),r={name:"201811/20181108 The Difference Between more, less And most Commands.md"};function h(g,e,m,k,u,b){const o=a("Link");return c(),n("div",null,[e[15]||(e[15]=p('<h1 id="more、less-和-most-的区别" tabindex="-1">more、less 和 most 的区别 <a class="header-anchor" href="#more、less-和-most-的区别" aria-label="Permalink to “more、less 和 most 的区别”">​</a></h1><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/11/more-less-and-most-commands-720x340.png" alt=""></p><p>如果你是一个 Linux 方面的新手，你可能会在 <code>more</code>、<code>less</code>、<code>most</code> 这三个命令行工具之间产生疑惑。在本文当中，我会对这三个命令行工具进行对比，以及展示它们各自在 Linux 中的一些使用例子。总的来说，这几个命令行工具之间都有相通和差异，而且它们在大部分 Linux 发行版上都有自带。</p><p>我们首先来看看 <code>more</code> 命令。</p><h3 id="more-命令" tabindex="-1">more 命令 <a class="header-anchor" href="#more-命令" aria-label="Permalink to “more 命令”">​</a></h3><p><code>more</code> 是一个老式的、基础的终端分页阅读器，它可以用于打开指定的文件并进行交互式阅读。如果文件的内容太长，在一屏以内无法完整显示，就会逐页显示文件内容。使用回车键或者空格键可以滚动浏览文件的内容，但有一个限制，就是只能够单向滚动。也就是说只能按顺序往下翻页，而不能进行回看。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/11/more-command-demo.gif" alt=""></p><p><strong>更正</strong></p><p>有的 Linux 用户向我指出，在 <code>more</code> 当中是可以向上翻页的。不过，最原始版本的 <code>more</code> 确实只允许向下翻页，在后续出现的较新的版本中也允许了有限次数的向上翻页，只需要在浏览过程中按 <code>b</code> 键即可向上翻页。唯一的限制是 <code>more</code> 不能搭配管道使用（如 <code>ls | more</code>）。（LCTT 译注：此处原作者疑似有误，译者使用 <code>more</code> 是可以搭配管道使用的，或许与不同 <code>more</code> 版本有关）</p><p>按 <code>q</code> 即可退出 <code>more</code>。</p><p><strong>更多示例</strong></p><p>打开 <code>ostechnix.txt</code> 文件进行交互式阅读，可以执行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ more ostechnix.txt</span></span></code></pre></div><p>在阅读过程中，如果需要查找某个字符串，只需要像下面这样输入斜杠（<code>/</code>）之后接着输入需要查找的内容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/linux</span></span></code></pre></div><p>按 <code>n</code> 键可以跳转到下一个匹配的字符串。</p><p>如果需要在文件的第 <code>10</code> 行开始阅读，只需要执行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ more +10 file</span></span></code></pre></div><p>就可以从文件的第 <code>10</code> 行开始显示文件的内容了。</p><p>如果你需要让 <code>more</code> 提示你按空格键来翻页，可以加上 <code>-d</code> 参数：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ more -d ostechnix.txt</span></span></code></pre></div><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/11/more-1.png" alt=""></p><p>如上图所示，<code>more</code> 会提示你可以按空格键翻页。</p><p>如果需要查看所有选项以及对应的按键，可以按 <code>h</code> 键。</p><p>要查看 <code>more</code> 的更多详细信息，可以参考手册：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ man more</span></span></code></pre></div><h3 id="less-命令" tabindex="-1">less 命令 <a class="header-anchor" href="#less-命令" aria-label="Permalink to “less 命令”">​</a></h3><p><code>less</code> 命令也是用于打开指定的文件并进行交互式阅读，它也支持翻页和搜索。如果文件的内容太长，也会对输出进行分页，因此也可以翻页阅读。比 <code>more</code> 命令更好的一点是，<code>less</code> 支持向上翻页和向下翻页，也就是可以在整个文件中任意阅读。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/11/less-command-demo.gif" alt=""></p><p>在使用功能方面，<code>less</code> 比 <code>more</code> 命令具有更多优点，以下列出其中几个：</p><ul><li>支持向上翻页和向下翻页</li><li>支持向上搜索和向下搜索</li><li>可以跳转到文件的末尾并立即从文件的开头开始阅读</li><li>在编辑器中打开指定的文件</li></ul><p><strong>更多示例</strong></p><p>打开文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ less ostechnix.txt</span></span></code></pre></div><p>按空格键或回车键可以向下翻页，按 <code>b</code> 键可以向上翻页。</p><p>如果需要向下搜索，在输入斜杠（<code>/</code>）之后接着输入需要搜索的内容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/linux</span></span></code></pre></div><p>按 <code>n</code> 键可以跳转到下一个匹配的字符串，如果需要跳转到上一个匹配的字符串，可以按 <code>N</code> 键。</p><p>如果需要向上搜索，在输入问号（<code>?</code>）之后接着输入需要搜索的内容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>?linux</span></span></code></pre></div><p>同样是按 <code>n</code> 键或 <code>N</code> 键跳转到下一个或上一个匹配的字符串。</p><p>只需要按 <code>v</code> 键，就会将正在阅读的文件在默认编辑器中打开，然后就可以对文件进行各种编辑操作了。</p><p>按 <code>h</code> 键可以查看 <code>less</code> 工具的选项和对应的按键。</p><p>按 <code>q</code> 键可以退出阅读。</p><p>要查看 <code>less</code> 的更多详细信息，可以参考手册：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ man less</span></span></code></pre></div><h3 id="most-命令" tabindex="-1">most 命令 <a class="header-anchor" href="#most-命令" aria-label="Permalink to “most 命令”">​</a></h3><p><code>most</code> 同样是一个终端阅读工具，而且比 <code>more</code> 和 <code>less</code> 的功能更为丰富。<code>most</code> 支持同时打开多个文件。你可以在打开的文件之间切换、编辑当前打开的文件、迅速跳转到文件中的某一行、分屏阅读、同时锁定或滚动多个屏幕等等功能。在默认情况下，对于较长的行，<code>most</code> 不会将其截断成多行显示，而是提供了左右滚动功能以在同一行内显示。</p><p><strong>更多示例</strong></p><p>打开文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ most ostechnix1.txt</span></span></code></pre></div><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/11/most-command.png" alt=""></p><p>按 <code>e</code> 键可以编辑当前文件。</p><p>如果需要向下搜索，在斜杠（<code>/</code>）或 <code>S</code> 或 <code>f</code> 之后输入需要搜索的内容，按 <code>n</code> 键就可以跳转到下一个匹配的字符串。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/11/most-1-1.gif" alt=""></p><p>如果需要向上搜索，在问号（<code>?</code>）之后输入需要搜索的内容，也是通过按 <code>n</code> 键跳转到下一个匹配的字符串。</p><p>同时打开多个文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ most ostechnix1.txt ostechnix2.txt ostechnix3.txt</span></span></code></pre></div><p>在打开了多个文件的状态下，可以输入 <code>:n</code> 切换到下一个文件，使用 <code>↑</code> 或 <code>↓</code> 键选择需要切换到的文件，按回车键就可以查看对应的文件。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/11/most-2.gif" alt=""></p><p>要打开文件并跳转到某个字符串首次出现的位置（例如 linux），可以执行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ most file +/linux</span></span></code></pre></div><p>按 <code>h</code> 键可以查看帮助。</p><p><strong>按键操作列表</strong></p><p>移动：</p><ul><li>空格键或 <code>D</code> 键 – 向下滚动一屏</li><li><code>DELETE</code> 键或 <code>U</code> 键 – 向上滚动一屏</li><li><code>↓</code> 键 – 向下移动一行</li><li><code>↑</code> 键 – 向上移动一行</li><li><code>T</code> 键 – 移动到文件开头</li><li><code>B</code> 键 – 移动到文件末尾</li><li><code>&gt;</code> 键或 <code>TAB</code> 键 – 向右滚动屏幕</li><li><code>&lt;</code> 键 – 向左滚动屏幕</li><li><code>→</code> 键 – 向右移动一列</li><li><code>←</code> 键 – 向左移动一列</li><li><code>J</code> 键或 <code>G</code> 键 – 移动到某一行，例如 <code>10j</code> 可以移动到第 10 行</li><li><code>%</code> 键 – 移动到文件长度某个百分比的位置</li></ul><p>窗口命令：</p><ul><li><code>Ctrl-X 2</code>、<code>Ctrl-W 2</code> – 分屏</li><li><code>Ctrl-X 1</code>、<code>Ctrl-W 1</code> – 只显示一个窗口</li><li><code>O</code> 键、<code>Ctrl-X O</code> – 切换到另一个窗口</li><li><code>Ctrl-X 0</code> – 删除窗口</li></ul><p>文件内搜索：</p><ul><li><code>S</code> 键或 <code>f</code> 键或 <code>/</code> 键 – 向下搜索</li><li><code>?</code> 键 – 向上搜索</li><li><code>n</code> 键 – 跳转到下一个匹配的字符串</li></ul><p>退出：</p><ul><li><code>q</code> 键 – 退出 <code>most</code> ，且所有打开的文件都会被关闭</li><li><code>:N</code>、<code>:n</code> – 退出当前文件并查看下一个文件（使用 <code>↑</code> 键、<code>↓</code> 键选择下一个文件）</li></ul><p>要查看 <code>most</code> 的更多详细信息，可以参考手册：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ man most</span></span></code></pre></div><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p><code>more</code> – 传统且基础的分页阅读工具，仅支持向下翻页和有限次数的向上翻页。</p><p><code>less</code> – 比 <code>more</code> 功能丰富，支持向下翻页和向上翻页，也支持文本搜索。在打开大文件的时候，比 <code>vi</code> 这类文本编辑器启动得更快。</p><p><code>most</code> – 在上述两个工具功能的基础上，还加入了同时打开多个文件、同时锁定或滚动多个屏幕、分屏等等大量功能。</p><p>以上就是我的介绍，希望能让你通过我的文章对这三个工具有一定的认识。如果想了解这篇文章以外的关于这几个工具的详细功能，请参阅它们的 <code>man</code> 手册。</p><hr>',80)),d("p",null,[e[1]||(e[1]=s("via: ",-1)),i(o,{href:"https://www.ostechnix.com/the-difference-between-more-less-and-most-commands/"},{default:t(()=>[...e[0]||(e[0]=[s("https://www.ostechnix.com/the-difference-between-more-less-and-most-commands/",-1)])]),_:1})]),d("p",null,[e[6]||(e[6]=s("作者：",-1)),i(o,{href:"https://www.ostechnix.com/author/sk/"},{default:t(()=>[...e[2]||(e[2]=[s("SK",-1)])]),_:1}),e[7]||(e[7]=s(" 选题：",-1)),i(o,{href:"https://github.com/lujun9972"},{default:t(()=>[...e[3]||(e[3]=[s("lujun9972",-1)])]),_:1}),e[8]||(e[8]=s(" 译者：",-1)),i(o,{href:"https://github.com/HankChow"},{default:t(()=>[...e[4]||(e[4]=[s("HankChow",-1)])]),_:1}),e[9]||(e[9]=s(" 校对：",-1)),i(o,{href:"https://github.com/wxy"},{default:t(()=>[...e[5]||(e[5]=[s("wxy",-1)])]),_:1})]),d("p",null,[e[12]||(e[12]=s("本文由 ",-1)),i(o,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...e[10]||(e[10]=[s("LCTT",-1)])]),_:1}),e[13]||(e[13]=s(" 原创编译，",-1)),i(o,{href:"https://linux.cn/"},{default:t(()=>[...e[11]||(e[11]=[s("Linux中国",-1)])]),_:1}),e[14]||(e[14]=s(" 荣誉推出",-1))])])}const w=l(r,[["render",h]]);export{C as __pageData,w as default};
